# Let's create test images with potential trigger patterns in each corner
# Trigger: 3-5 pixels wide, 1 pixel in from corner
# We'll test different patch types and corners

def create_patch_image(patch_type="white", patch_size=4, corner="top_left"):
    """Create a clean image with a patch added."""
    # Start with a clean image (first clean image)
    img = x_clean[0:1].clone().float()  # (1, 3, 32, 32)

    # Patch position: 1 pixel in from corner
    if corner == "top_left":
        h_start, w_start = 1, 1
    elif corner == "top_right":
        h_start, w_start = 1, 32 - 1 - patch_size
    elif corner == "bottom_left":
        h_start, w_start = 32 - 1 - patch_size, 1
    elif corner == "bottom_right":
        h_start, w_start = 32 - 1 - patch_size, 32 - 1 - patch_size

    h_end = h_start + patch_size
    w_end = w_start + patch_size

    if patch_type == "white":
        # White patch (255 in all channels)
        patch_val = 255
        img[0, :, h_start:h_end, w_start:w_end] = patch_val
    elif patch_type == "checkerboard":
        # Checkerboard pattern
        for c in range(3):
            for i in range(patch_size):
                for j in range(patch_size):
                    val = 255 if (i + j) % 2 == 0 else 0
                    img[0, c, h_start + i, w_start + j] = val
    elif patch_type == "random_noise":
        # Random black/white
        noise = torch.randint(0, 2, (3, patch_size, patch_size)) * 255
        img[0, :, h_start:h_end, w_start:w_end] = noise

    return img.to(torch.uint8)

# Test different patch configurations on a single clean image
corners = ["top_left", "top_right", "bottom_left", "bottom_right"]
patch_types = ["white", "checkerboard", "random_noise"]
patch_sizes = [3, 4, 5]

# Test all combinations
for patch_type in patch_types:
    for patch_size in patch_sizes:
        for corner in corners:
            img = create_patch_image(patch_type, patch_size, corner)
            logits = forward(W, img)
            pred = logits.argmax(dim=1).item()
            print(f"Patch: {patch_type}, size={patch_size}, corner={corner} -> Class {pred} ({CLASSES[pred]})")

print(f"\nPasses left: {passes_left()}")
